<?php
require_once dirname(__DIR__).'/services/userService.php';
require_once dirname(__DIR__).'/repositories/studentPDO.php';
require_once dirname(__DIR__).'/repositories/requestPDO.php';
$pdo=new PDO('sqlite::memory:');$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$pdo->exec('PRAGMA foreign_keys=ON');$pdo->exec(file_get_contents(dirname(__DIR__).'/database/setup-database.sql'));
$passed=0;$failed=0;function check($condition,$label){global $passed,$failed;if($condition){$passed++;echo "PASS: $label\n";}else{$failed++;echo "FAIL: $label\n";}}
$studentId=registerUser($pdo,['full_name'=>'Jordan Lee','email'=>'jordan@example.edu','password'=>'StrongPass123','confirm_password'=>'StrongPass123','role'=>'Student']);$student=findUserById($pdo,$studentId);check($student['status']==='Active'&&$student['role']==='Student','UM-01 valid Student registration creates Active user');
try{registerUser($pdo,['full_name'=>'Bad Admin','email'=>'bad@example.edu','password'=>'StrongPass123','confirm_password'=>'StrongPass123','role'=>'Administrator']);check(false,'UM-01 public Administrator registration rejected');}catch(InvalidArgumentException $e){check(true,'UM-01 public Administrator registration rejected');}
try{registerUser($pdo,['full_name'=>'Duplicate','email'=>'jordan@example.edu','password'=>'StrongPass123','confirm_password'=>'StrongPass123','role'=>'Tutor']);check(false,'UM-01 duplicate email rejected');}catch(InvalidArgumentException $e){check(true,'UM-01 duplicate email rejected');}
check(authenticateUser($pdo,'jordan@example.edu','StrongPass123')!==false,'UM-09 valid password authenticates');check(authenticateUser($pdo,'jordan@example.edu','wrong')===false,'UM-09 invalid password rejected');
saveOwnProfile($pdo,$studentId,['full_name'=>'Jordan Updated','email'=>'jordan.updated@example.edu']);check(findUserById($pdo,$studentId)['full_name']==='Jordan Updated','UM-04 own profile update persists');
try{changeOwnPassword($pdo,$studentId,['current_password'=>'wrong','new_password'=>'NewStrong123','confirm_password'=>'NewStrong123']);check(false,'UM-05 wrong current password rejected');}catch(InvalidArgumentException $e){check(true,'UM-05 wrong current password rejected');}changeOwnPassword($pdo,$studentId,['current_password'=>'StrongPass123','new_password'=>'NewStrong123','confirm_password'=>'NewStrong123']);check(authenticateUser($pdo,'jordan.updated@example.edu','NewStrong123')!==false,'UM-05 new password works');
$adminId=insertUser($pdo,'Test Administrator','admin@example.edu',password_hash('AdminStrong123',PASSWORD_DEFAULT),'Administrator');$admin=findUserById($pdo,$adminId);check(count(searchUsers($pdo,'Jordan','',''))===1,'UM-03 administrator search finds account');setManagedStatus($pdo,$studentId,'Inactive');check(authenticateUser($pdo,'jordan.updated@example.edu','NewStrong123')===false,'UM-07 inactive user cannot log in');setManagedStatus($pdo,$studentId,'Active');setManagedRole($pdo,$studentId,'Tutor');check(findUserById($pdo,$studentId)['role']==='Tutor','UM-06 administrator role update persists');
try{setManagedStatus($pdo,(int)$admin['user_id'],'Inactive');check(false,'UM-07 last active administrator protected');}catch(DomainException $e){check(true,'UM-07 last active administrator protected');}
$orphan=registerUser($pdo,['full_name'=>'Delete Me','email'=>'delete@example.edu','password'=>'StrongPass123','confirm_password'=>'StrongPass123','role'=>'Tutor']);check(removeManagedUser($pdo,$orphan)&&!findUserById($pdo,$orphan),'UM-08 account without related records deleted');
ensureStudentForUser($pdo,findUserById($pdo,$studentId));try{removeManagedUser($pdo,$studentId);check(false,'UM-08 account with related student record blocked');}catch(DomainException $e){check(true,'UM-08 account with related student record blocked');}
echo "Results: $passed passed, $failed failed\n";exit($failed>0?1:0);
